PHONE_SERVICE_WORKER = r'''"use strict";
const CACHE="jarvis-os-phone-v2",OFFLINE="/phone-offline";
self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.add(OFFLINE)));self.skipWaiting()});
self.addEventListener("activate",event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener("fetch",event=>{const url=new URL(event.request.url);if(event.request.mode==="navigate"&&url.origin===location.origin&&url.pathname==="/phone"){event.respondWith(fetch(event.request).catch(()=>caches.match(OFFLINE)))}});
'''

PHONE_LOGIN_PAGE = r'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#03121f"><title>JARVIS OS — logowanie</title><style>:root{color-scheme:dark;font-family:Inter,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;color:#dff7ff;background:radial-gradient(circle at 50% -10%,#08385a,#020b13 55%);padding:20px}.card{width:min(520px,100%);text-align:center;background:#03131fe8;border:1px solid #0e6281;border-radius:20px;padding:28px;box-shadow:0 14px 50px #0009}h1{letter-spacing:.2em;margin:0 0 8px}p{color:#91bbca;line-height:1.55}.button{display:block;margin-top:22px;border:1px solid #31cce9;border-radius:12px;background:linear-gradient(135deg,#0c7898,#0b4866);color:#fff;padding:14px 18px;font-weight:700;text-decoration:none}.hint{font-size:12px;color:#739baa}</style></head><body><main class="card"><h1>JARVIS OS</h1><p>Telefon łączy się teraz przez Twoje konto Microsoft. Stały kod parowania nie jest już potrzebny.</p><a class="button" href="/.auth/login/aad?post_login_redirect_uri=%2Fphone">ZALOGUJ PRZEZ MICROSOFT</a><a class="button" href="/phone-recover">NAPRAW BIAŁY EKRAN</a><p class="hint">Sesja wygasa po 60 minutach. Ważne działania nadal wymagają potwierdzenia na komputerze.</p></main></body></html>'''

