PHONE_RECOVERY_PAGE = r'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#03121f"><title>JARVIS OS — naprawa telefonu</title><style>:root{color-scheme:dark;font-family:Inter,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;color:#dff7ff;background:radial-gradient(circle at 50% -10%,#08385a,#020b13 55%);padding:20px}.card{width:min(520px,100%);text-align:center;background:#03131fe8;border:1px solid #0e6281;border-radius:20px;padding:28px;box-shadow:0 14px 50px #0009}p{color:#91bbca;line-height:1.55}button,a{display:block;width:100%;margin-top:18px;border:1px solid #31cce9;border-radius:12px;background:linear-gradient(135deg,#0c7898,#0b4866);color:#fff;padding:14px 18px;font:inherit;font-weight:700;text-decoration:none}button:disabled{opacity:.55}</style></head><body><main class="card"><h1>Naprawiam połączenie</h1><p id="status">Usuwam starą wersję aplikacji i kończę poprzednią sesję…</p><button id="repair" type="button">NAPRAW PONOWNIE</button><a href="/phone">WRÓĆ DO LOGOWANIA</a></main><script>(()=>{"use strict";const status=document.querySelector("#status"),button=document.querySelector("#repair");async function repair(){button.disabled=true;status.textContent="Usuwam starą wersję aplikacji i kończę poprzednią sesję…";try{if("serviceWorker" in navigator){const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.filter(item=>item.scope.startsWith(location.origin+"/phone")).map(item=>item.unregister()))}}catch(_error){}try{if("caches" in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith("jarvis-os-phone-")).map(key=>caches.delete(key)))}}catch(_error){}for(const key of ["jarvisLastCommand","jarvisPendingRequest","jarvisPhoneDevice"]){sessionStorage.removeItem(key)}try{await fetch("/.auth/logout",{credentials:"include",cache:"no-store"})}catch(_error){}location.replace("/phone?recovered="+Date.now())}button.addEventListener("click",repair);repair()})();</script></body></html>'''
PHONE_PAGE = r'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#03121f"><link rel="manifest" href="/phone.webmanifest"><link rel="icon" href="/phone-icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/phone-icon.svg"><title>JARVIS OS &mdash; telefon</title>
<style>:root{color-scheme:dark;font-family:Inter,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#dff7ff;background:radial-gradient(circle at 50% -10%,#08385a,#020b13 55%)}main{width:min(720px,100%);margin:auto;padding:28px 18px 44px}header{text-align:center;margin-bottom:24px}h1{margin:0;letter-spacing:.22em;font-size:clamp(25px,7vw,40px)}header p{color:#73cdea;margin:8px 0 0;letter-spacing:.08em}.card{background:#03131fe8;border:1px solid #0e6281;border-radius:18px;padding:18px;box-shadow:0 14px 50px #0009;margin:14px 0}label{display:block;color:#83d5ed;font-size:13px;margin:12px 0 6px}input,textarea,button,.button{width:100%;border-radius:12px;font:inherit}input,textarea{color:#eaffff;background:#010b13;border:1px solid #175f78;padding:13px;outline:none}input:focus,textarea:focus{border-color:#3edbff;box-shadow:0 0 0 3px #1cc8ed22}textarea{min-height:104px;resize:vertical}button,.button{display:block;text-align:center;border:1px solid #31cce9;background:linear-gradient(135deg,#0c7898,#0b4866);color:white;padding:13px 16px;font-weight:700;cursor:pointer;text-decoration:none}button:disabled{opacity:.55;cursor:wait}.quick,.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:10px 0 14px}.quick button,.secondary{background:#082739;font-weight:600;padding:10px}.danger{border-color:#9f4b5a;background:#38131c}.connection{display:flex;align-items:center;gap:9px;border:1px solid #174b60;border-radius:12px;padding:10px 12px;margin-bottom:12px;color:#91bbca;font-size:13px;letter-spacing:.05em}.dot{width:10px;height:10px;border-radius:50%;background:#70838b;box-shadow:0 0 0 4px #70838b18}.dot.checking{background:#ffd77a;box-shadow:0 0 12px #ffd77a}.dot.online{background:#67f7c7;box-shadow:0 0 12px #67f7c7}.dot.offline{background:#ff8c9d;box-shadow:0 0 12px #ff8c9d}.status{min-height:96px;display:grid;align-content:center;text-align:center}.pill{display:inline-block;justify-self:center;padding:6px 12px;border-radius:999px;border:1px solid #176d88;color:#84def4;margin-bottom:10px}#message{white-space:pre-wrap;line-height:1.5}.hint{color:#7aa5b6;font-size:12px;line-height:1.45}.account{display:flex;justify-content:space-between;gap:12px;align-items:center}.account strong{overflow-wrap:anywhere}.ok{color:#67f7c7}.warn{color:#ffd77a}.bad{color:#ff8c9d}[hidden]{display:none!important}@media(max-width:480px){.actions{grid-template-columns:1fr}.account{display:block}.account span{display:block;margin-top:5px}}</style></head>
<body><main><header><h1>JARVIS OS</h1><p>BEZPIECZNY MOST TELEFONU</p></header><section class="card"><div class="account"><strong id="accountName">KONTO MICROSOFT</strong><span class="ok">SESJA AKTYWNA</span></div><p class="hint">Sesja wygasa po 60 minutach. Ważne działania nadal wymagają potwierdzenia na komputerze.</p><div class="connection"><span id="connectionDot" class="dot"></span><strong id="connectionText">SPRAWDZAM KOMPUTER…</strong></div><label for="device">Urządzenie</label><input id="device" value="desktop-main" maxlength="64" autocapitalize="none"></section><section class="card"><div class="quick"><button type="button" data-command="status systemu">STATUS SYSTEMU</button><button type="button" data-command="status chmury">STATUS CHMURY</button></div><label for="command">Polecenie</label><textarea id="command" maxlength="4000" placeholder="Napisz, co JARVIS ma zrobić?"></textarea><button id="send" type="button">WYŚLIJ DO KOMPUTERA</button></section><section class="card status" aria-live="polite"><span id="pill" class="pill">GOTOWY</span><div id="message">Wyślij pierwsze polecenie. Ostatni wynik wróci po odświeżeniu strony.</div></section><section class="card"><div class="actions"><button id="install" class="secondary" type="button" hidden>ZAINSTALUJ APLIKACJĘ</button><a class="button secondary" href="https://account.microsoft.com/security" target="_blank" rel="noopener">ZGUBIONY TELEFON</a><a class="button danger" href="/phone-recover">WYLOGUJ TEN TELEFON</a></div><p id="installHint" class="hint">Aby odebrać dostęp zgubionemu telefonowi, otwórz „Moje logowania” Microsoft i wyloguj jego sesję. Dostęp JARVIS OS i tak wygaśnie najpóźniej po godzinie.</p></section></main>
<script>(()=>{"use strict";const device=document.querySelector("#device"),command=document.querySelector("#command"),send=document.querySelector("#send"),pill=document.querySelector("#pill"),message=document.querySelector("#message"),connectionDot=document.querySelector("#connectionDot"),connectionText=document.querySelector("#connectionText"),accountName=document.querySelector("#accountName"),install=document.querySelector("#install"),installHint=document.querySelector("#installHint");let currentId="",pollTimer=0,probeId="",probeTimer=0,probeDeadline=0,installPrompt=null;const labels={queued:"W KOLEJCE",claimed:"ODEBRANE",waiting_local_confirmation:"CZEKA NA KOMPUTERZE",completed:"GOTOWE",failed:"NIEUDANE",cancelled:"ANULOWANE",expired:"WYGASŁO"},terminal=new Set(["completed","failed","cancelled","expired"]),lastKey="jarvisLastCommand";
function targetDevice(){const value=device.value.trim().toLowerCase();if(!/^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/.test(value))throw new Error("Nieprawidłowa nazwa urządzenia.");sessionStorage.setItem("jarvisPhoneDevice",value);return value}function show(state,text){pill.textContent=labels[state]||state.toUpperCase();pill.className="pill "+(state==="completed"?"ok":terminal.has(state)?"bad":state==="waiting_local_confirmation"?"warn":"");message.textContent=text||"Brak dodatkowych informacji."}function connection(state,text){connectionDot.className="dot "+state;connectionText.textContent=text}async function api(path,options){const response=await fetch(path,Object.assign({credentials:"same-origin"},options||{},{headers:Object.assign({Accept:"application/json"},options&&options.headers||{})})),data=await response.json().catch(()=>({}));if(response.status===401){location.replace("/phone");throw new Error("Sesja wygasła.")}if(!response.ok)throw new Error(data.message||data.error||"Połączenie nie powiodło się.");return data}function newRequestId(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,value=>value.toString(16).padStart(2,"0")).join("")}async function requestIdFor(target,value){const input=new TextEncoder().encode(target+"\0"+value),digest=await crypto.subtle.digest("SHA-256",input),signature=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,"0")).join(""),key="jarvisPendingRequest";let stored={};try{stored=JSON.parse(sessionStorage.getItem(key)||"{}")}catch(_error){}if(!/^[a-f0-9]{32}$/.test(stored.id||"")||stored.signature!==signature){stored={id:newRequestId(),signature};sessionStorage.setItem(key,JSON.stringify(stored))}return stored.id}function clearPendingRequest(){sessionStorage.removeItem("jarvisPendingRequest")}function remember(id,target){sessionStorage.setItem(lastKey,JSON.stringify({id,device_id:target}))}function restoreReference(){try{const saved=JSON.parse(sessionStorage.getItem(lastKey)||"{}");if(/^[a-f0-9]{32}$/.test(saved.id||"")&&/^[a-z0-9-]{1,64}$/.test(saved.device_id||"")){currentId=saved.id;device.value=saved.device_id;return true}}catch(_error){}return false}async function refresh(){if(!currentId)return;try{const data=await api("/v1/remote/commands/"+encodeURIComponent(currentId)+"?device_id="+encodeURIComponent(targetDevice()));show(data.status,data.message);if(terminal.has(data.status)){clearInterval(pollTimer);send.disabled=false}}catch(error){show("failed",error.message);clearInterval(pollTimer);send.disabled=false}}async function submit(){const value=command.value.trim();if(!value)return show("failed","Wpisz polecenie.");let target;try{target=targetDevice()}catch(error){return show("failed",error.message)}send.disabled=true;show("queued","Wysyłam polecenie…");try{const data=await api("/v1/remote/commands",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({device_id:target,command:value,request_id:await requestIdFor(target,value)})});clearPendingRequest();currentId=data.id;remember(data.id,target);show(data.status,data.message);clearInterval(pollTimer);pollTimer=setInterval(refresh,1500);refresh()}catch(error){show("failed",error.message+" Możesz bezpiecznie nacisnąć WYŚLIJ ponownie.");send.disabled=false}}async function checkProbe(){if(!probeId)return;try{const data=await api("/v1/remote/commands/"+encodeURIComponent(probeId)+"?device_id="+encodeURIComponent(targetDevice()));if(data.status==="completed"){connection("online","KOMPUTER ONLINE");probeId="";return}if(terminal.has(data.status)||Date.now()>probeDeadline){connection("offline","KOMPUTER NIE ODPOWIADA");probeId="";return}probeTimer=setTimeout(checkProbe,1000)}catch(_error){connection("offline","BRAK POŁĄCZENIA");probeId=""}}async function probe(){clearTimeout(probeTimer);probeId="";let target;try{target=targetDevice()}catch(error){connection("offline",error.message.toUpperCase());return}connection("checking","SPRAWDZAM KOMPUTER…");try{const data=await api("/v1/remote/probe",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({device_id:target,request_id:newRequestId()})});probeId=data.id;probeDeadline=Date.now()+20000;probeTimer=setTimeout(checkProbe,500)}catch(_error){connection("offline","BRAK POŁĄCZENIA")}}async function loadIdentity(){try{const data=await api("/v1/phone/me");accountName.textContent=data.name||"KONTO MICROSOFT"}catch(_error){}}
window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();installPrompt=event;install.hidden=false});install.addEventListener("click",async()=>{if(!installPrompt)return;installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;install.hidden=true;installHint.textContent=choice.outcome==="accepted"?"JARVIS OS został dodany do telefonu.":"Możesz zainstalować aplikację później z menu przeglądarki."});window.addEventListener("appinstalled",()=>{install.hidden=true;installHint.textContent="JARVIS OS jest zainstalowany na tym telefonie."});document.querySelectorAll("[data-command]").forEach(button=>button.addEventListener("click",()=>{command.value=button.dataset.command}));send.addEventListener("click",submit);device.addEventListener("change",probe);device.value=sessionStorage.getItem("jarvisPhoneDevice")||device.value;if("serviceWorker" in navigator)navigator.serviceWorker.register("/phone-sw.js",{scope:"/phone"});loadIdentity();if(restoreReference())refresh();setTimeout(probe,250)})();</script></body></html>'''